input.command:
cd /uufs/chpc.utah.edu/common/home/chet/Daisy/Thesis/runs/E2_interrupted_recovery_example16/clio/trial_04/work && source /uufs/chpc.utah.edu/common/home/chet/Daisy/Thesis/common/scripts/load_approved_software.sh >/dev/null 2>&1; mkdir -p scratch_xml/legacy scratch_xml/bsp05 scratch_xml/outfreq scratch_xml/isofreq; 
# (a) legacy study-level form
sed -e '/^begin filter 1/,/^end filter/d' -e 's/^  filter_ids 1$/  filter_type helmholtz\n  filter_radius_absolute 0.15\n  boundary_sticking_penalty 1.0/' stage1/input_deck.i > scratch_xml/legacy/input_deck.i; 
# (b) block form with sticking 0.5 to prove block values propagate
sed -e 's/^  boundary_sticking_penalty 1.0$/  boundary_sticking_penalty 0.5/' stage1/input_deck.i > scratch_xml/bsp05/input_deck.i; 
# (c) output_frequency 1 in output block
sed -e 's/^  data dispx dispy dispz$/  data dispx dispy dispz\n  output_frequency 1/' stage1/input_deck.i > scratch_xml/outfreq/input_deck.i; 
# (d) isosurface_output_frequency 1 in study block
sed -e 's/^  write_restart_file true$/  write_restart_file true\n  isosurface_output_frequency 1/' stage1/input_deck.i > scratch_xml/isofreq/input_deck.i; 
for d in legacy bsp05 outfreq isofreq; do (cd scratch_xml/$d && cp ../../mesh/mesh.exo . && XMLGenerator input_deck.i > xmlgenerator.log 2>&1; echo "$d rc=$?"; grep -E 'Length Scale' analyze_helmholtz_input_deck.xml; grep -E 'OutputFrequency' engine_operations.xml analyze_2_operations.xml; grep -i -E 'error|warn' xmlgenerator.log | head -3); done; echo ====DIFF legacy vs block; for f in interface.xml engine_operations.xml analyze_2_input_deck.xml analyze_helmholtz_input_deck.xml analyze_2_operations.xml analyze_helmholtz_operations.xml engine_input_deck.xml mpirun.source; do diff -q stage1/run/$f scratch_xml/legacy/$f; done; echo diffdone
